  (
    {
      children,
      loading = false,
      disabled = false,
      icon,
      fullWidth = false,
      size = 'md',
      type = 'button',
      className,
      onClick,
      ...rest
    },
    ref
  ) => {
    const isDisabled = disabled || loading;

    const classes = [
      styles.button,
      styles[size],
      fullWidth && styles.fullWidth,
      loading && styles.loading,
      className,
