## `PrimaryButton.jsx`

```jsx
import React from 'react';
import './PrimaryButton.css';

/**
 * PrimaryButton - the main call-to-action button.
 *
 * @param {React.ReactNode} children - Button label/content
 * @param {function} onClick - Click handler
 * @param {boolean} disabled - Disables the button
 * @param {boolean} loading - Shows a spinner and blocks interaction
 * @param {'button'|'submit'|'reset'} type - Native button type
 * @param {'sm'|'md'|'lg'} size - Button size
 * @param {boolean} fullWidth - Stretch to container width
 * @param {React.ReactNode} icon - Optional leading icon
 * @param {string} className - Additional class names
 */
const PrimaryButton = React.forwardRef(
  (
    {
      children,
      onClick,
      disabled = false,
      loading = false,
      type = 'button',
      size = 'md',
      fullWidth = false,
      icon = null,
      className = '',
      ...rest
    },
    ref
  ) => {
    const isDisabled = disabled || loading;

    const handleClick = (event) => {
      if (isDisabled) {
        event.preventDefault();
        return;
      }
      onClick?.(event);
    };

    const classes = [
      'primary-btn',
      `primary-btn--${size}`,
      fullWidth && 'primary-btn--full',
      loading && 'primary-btn--loading',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <button
        ref={ref}
        type={type}
        className={classes}
        onClick={handleClick}
        disabled={isDisabled}
        aria-disabled={isDisabled}
        aria-busy={loading}
        {...rest}
      >
        {loading && <span className="primary-btn__spinner" aria-hidden="true" />}
        {!loading && icon && (
          <span className="primary-btn__icon" aria-hidden="true">
            {icon}
          </span>
        )}
        <span className="primary-btn__label">{children}</span>
      </button>
    );
  }
);

PrimaryButton.displayName = 'PrimaryButton';

export default PrimaryButton;
```

