## `PrimaryButton.tsx`

```tsx
import React from 'react';
import './PrimaryButton.css';

type ButtonSize = 'sm' | 'md' | 'lg';

export interface PrimaryButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Visual size of the button */
  size?: ButtonSize;
  /** Shows a spinner and disables interaction */
  loading?: boolean;
  /** Stretch to fill container width */
  fullWidth?: boolean;
  /** Optional icon rendered before the label */
  leftIcon?: React.ReactNode;
  /** Optional icon rendered after the label */
  rightIcon?: React.ReactNode;
}

export const PrimaryButton = React.forwardRef<HTMLButtonElement, PrimaryButtonProps>(
  (
    {
      children,
      size = 'md',
      loading = false,
      fullWidth = false,
      disabled = false,
      leftIcon,
      rightIcon,
      className = '',
      type = 'button',
      onClick,
      ...rest
    },
    ref
  ) => {
    const isDisabled = disabled || loading;

    const classes = [
      'primary-btn',
      `primary-btn--${size}`,
      fullWidth && 'primary-btn--full',
      loading && 'primary-btn--loading',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (isDisabled) {
        e.preventDefault();
        return;
      }
      onClick?.(e);
    };

    return (
      <button
        ref={ref}
        type={type}
        className={classes}
        disabled={isDisabled}
        aria-disabled={isDisabled}
        aria-busy={loading}
        onClick={handleClick}
        {...rest}
      >
        {loading && <span className="primary-btn__spinner" aria-hidden="true" />}
        {!loading && leftIcon && (
          <span className="primary-btn__icon" aria-hidden="true">{leftIcon}</span>
        )}
        <span className="primary-btn__label">{children}</span>
        {!loading && rightIcon && (
          <span className="primary-btn__icon" aria-hidden="true">{rightIcon}</span>
        )}
      </button>
    );
  }
);

PrimaryButton.displayName = 'PrimaryButton';

export default PrimaryButton;
```

