Here's an accessible React modal component with a darkened backdrop and a centered panel. It includes portal rendering, keyboard support, focus management, scroll locking, and enter/exit animations.

## Modal.jsx

```jsx
import { useEffect, useRef, useState, useCallback } from "react";
import { createPortal } from "react-dom";
import "./Modal.css";

const FOCUSABLE_SELECTORS =
  'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])';

const ANIMATION_DURATION = 200; // ms — keep in sync with CSS

export default function Modal({
  isOpen,
  onClose,
  title,
  children,
  footer,
  size = "medium", // "small" | "medium" | "large"
  closeOnBackdropClick = true,
  closeOnEscape = true,
}) {
  const panelRef = useRef(null);
  const previouslyFocused = useRef(null);
  const [isMounted, setIsMounted] = useState(isOpen);
  const [isVisible, setIsVisible] = useState(false);

  // Handle mount/unmount with animation
  useEffect(() => {
    if (isOpen) {
      setIsMounted(true);
      // Next frame so the CSS transition actually runs
      const raf = requestAnimationFrame(() => setIsVisible(true));
      return () => cancelAnimationFrame(raf);
    } else {
      setIsVisible(false);
      const timer = setTimeout(() => setIsMounted(false), ANIMATION_DURATION);
      return () => clearTimeout(timer);
    }
  }, [isOpen]);

  // Save and restore focus
  useEffect(() => {
    if (!isOpen) return;
    previouslyFocused.current = document.activeElement;

    const focusTimer = setTimeout(() => {
      const focusable = panelRef.current?.querySelectorAll(FOCUSABLE_SELECTORS);
      (focusable?.[0] ?? panelRef.current)?.focus();
    }, 0);

    return () => {
      clearTimeout(focusTimer);
      previouslyFocused.current?.focus?.();
    };
  }, [isOpen]);

  // Lock body scroll
  useEffect(() => {
    if (!isOpen) return;
    const { overflow, paddingRight } = document.body.style;
    const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth;

    document.body.style.overflow = "hidden";
    if (scrollbarWidth > 0) {
      document.body.style.paddingRight = `${scrollbarWidth}px`; // prevent layout shift
    }

    return () => {
      document.body.style.overflow = overflow;
      document.body.style.paddingRight = paddingRight;
    };
  }, [isOpen]);

  // Escape key + focus trap
  const handleKeyDown = useCallback(
    (e) => {
      if (e.key === "Escape" && closeOnEscape) {
        e.stopPropagation();
        onClose();
        return;
      }

      if (e.key === "Tab" && panelRef.current) {
        const focusable = Array.from(
          panelRef.current.querySelectorAll(FOCUSABLE_SELECTORS)
        );
        if (focusable.length === 0) {
          e.preventDefault();
          return;
        }
        const first = focusable[0];
        const last = focusable[focusable.length - 1];

        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault();
          last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    },
    [closeOnEscape, onClose]
  );

  // Only close when the click both starts and ends on the backdrop
  // (prevents closing when the user drags a text selection out of the panel)
  const mouseDownTarget = useRef(null);
  const handleBackdropMouseDown = (e) => {
    mouseDownTarget.current = e.target;
  };
  const handleBackdropClick = (e) => {
    if (
      closeOnBackdropClick &&
      e.target === e.currentTarget &&
      mouseDownTarget.current === e.currentTarget
    ) {
      onClose();
    }
  };

  if (!isMounted) return null;

  return createPortal(
    <div
      className={`modal-backdrop ${isVisible ? "modal-backdrop--visible" : ""}`}
      onMouseDown={handleBackdropMouseDown}
      onClick={handleBackdropClick}
      onKeyDown={handleKeyDown}
    >
      <div
        ref={panelRef}
        className={`modal-panel modal-panel--${size} ${
          isVisible ? "modal-panel--visible" : ""
        }`}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? "modal-title" : undefined}
        tabIndex={-1}
      >
        <header className="modal-header">
          {title && (
            <h2 id="modal-title" className="modal-title">
              {title}
            </h2>
          )}
          <button
            type="button"
            className="modal-close"
            onClick={onClose}
            aria-label="Close modal"
          >
            ×
          </button>
        </header>

        <div className="modal-body">{children}</div>

        {footer && <footer className="modal-footer">{footer}</footer>}
      </div>
    </div>,
    document.body
  );
}
```

