Here is a reusable React component for a primary action button using TypeScript and Tailwind CSS. It includes default, hover, active, focus, and disabled states.

### `PrimaryButton.tsx`

```tsx
import React from 'react';

interface PrimaryButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  children: React.ReactNode;
}

export const PrimaryButton: React.FC<PrimaryButtonProps> = ({
  children,
  disabled = false,
  className = '',
  type = 'button',
  ...props
}) => {
  return (
    <button
      type={type}
      disabled={disabled}
      className={`
        inline-flex items-center justify-center
        px-5 py-2.5 rounded-lg font-medium text-white
        bg-blue-600 transition-colors duration-200
        hover:bg-blue-700 active:bg-blue-800
        focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2
        disabled:bg-blue-300 disabled:cursor-not-allowed disabled:hover:bg-blue-300
        ${className}
      `}
      {...props}
    >
      {children}
    </button>
  );
};
```

### Usage Example

```tsx
import { PrimaryButton } from './PrimaryButton';

export default function App() {
  return (
    <div className="flex gap-4 p-6">
      {/* Default & Hover State */}
      <PrimaryButton onClick={() => alert('Clicked!')}>
        Save Changes
      </PrimaryButton>

      {/* Disabled State */}
      <PrimaryButton disabled>
        Submit
      </PrimaryButton>
    </div>
  );
}
```

### Key Features
* **Hover & Active States:** Darkens smoothly (`transition-colors duration-200`) on hover (`hover:bg-blue-700`) and click (`active:bg-blue-800`).
* **Disabled State:** Uses a lighter background (`disabled:bg-blue-300`), prevents the hover color change, and shows the not-allowed cursor (`disabled:cursor-not-allowed`).
* **Accessibility:** Extends standard HTML button attributes (supporting `onClick`, `aria-*`, `type`, etc.) and includes a visible focus ring for keyboard navigation.

