### Key Features Included
* **Portal rendering**: Uses `createPortal` to mount the modal directly to `document.body`, avoiding `z-index` or `overflow: hidden` issues from parent containers.
* **Dismissal**: Closes when clicking the darkened backdrop, clicking the close button, or pressing the `Escape` key.
* **Scroll lock**: Disables background page scrolling while the modal is open and restores it on close.
* **Accessibility**: Includes `role="dialog"`, `aria-modal="true"`, and proper labeling.

Here is a reusable, accessible React modal component using React Portals, complete with Escape-key closing, backdrop-click closing, and scroll locking.

### 1. The Modal Component (`Modal.jsx`)

```jsx
import React, { useEffect } from 'react';
import { createPortal } from 'react-dom';
import './Modal.css';

export function Modal({ isOpen, onClose, title, children }) {
  useEffect(() => {
    if (!isOpen) return;

    // Close on Escape key
    const handleKeyDown = (e) => {
      if (e.key === 'Escape') onClose();
    };

    // Prevent background scrolling while modal is open
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.body.style.overflow = originalOverflow;
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return createPortal(
    <div
      className="modal-backdrop"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-labelledby={title ? 'modal-title' : undefined}
    >
      <div
        className="modal-panel"
        onClick={(e) => e.stopPropagation()} // Prevent closing when clicking inside the panel
      >
        <div className="modal-header">
          {title && <h2 id="modal-title" className="modal-title">{title}</h2>}
          <button
            type="button"
            className="modal-close-btn"
            onClick={onClose}
            aria-label="Close modal"
          >
            &times;
          </button>
        </div>
        <div className="modal-body">{children}</div>
      </div>
    </div>,
    document.body
  );
}
```

