# Primary Action Button Component

```jsx
import React from 'react';
import './PrimaryButton.css';

const PrimaryButton = ({
  children,
  onClick,
  disabled = false,
  type = 'button',
  fullWidth = false,
  size = 'medium',
  ariaLabel,
}) => {
  const handleClick = (e) => {
    if (disabled) return;
    onClick?.(e);
  };

  const handleKeyDown = (e) => {
    if (disabled) return;
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onClick?.(e);
    }
  };

  const classes = [
    'primary-btn',
    `primary-btn--${size}`,
    fullWidth ? 'primary-btn--full' : '',
    disabled ? 'primary-btn--disabled' : '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <button
      type={type}
      className={classes}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      disabled={disabled}
      aria-label={ariaLabel}
      aria-disabled={disabled}
    >
      {children}
    </button>
  );
};

export default PrimaryButton;
```

