Here's a clean, reusable product card component:

## ProductCard.jsx

```jsx
import React, { useState } from 'react';
import './ProductCard.css';

function ProductCard({ product, onAddToCart }) {
  const [isHovered, setIsHovered] = useState(false);

  const {
    image,
    title,
    price,
    originalPrice,
    rating,
    inStock = true,
  } = product;

  const discount = originalPrice
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : 0;

  const formatPrice = (value) =>
    new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
    }).format(value);

  return (
    <div
      className="product-card"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div className="product-card__image-container">
        <img
          className="product-card__image"
          src={image}
          alt={title}
          loading="lazy"
        />
        {discount > 0 && (
          <span className="product-card__badge product-card__badge--discount">
            -{discount}%
          </span>
        )}
        {!inStock && (
          <span className="product-card__badge product-card__badge--out-of-stock">
            Out of Stock
          </span>
        )}
      </div>

      <div className="product-card__content">
        {rating && (
          <div className="product-card__rating" aria-label={`Rated ${rating} out of 5`}>
            {'★'.repeat(Math.floor(rating))}
            <span className="product-card__rating-value">{rating}</span>
          </div>
        )}

        <h3 className="product-card__title">{title}</h3>

        <div className="product-card__price-row">
          <span className="product-card__price">{formatPrice(price)}</span>
          {originalPrice && (
            <span className="product-card__original-price">
              {formatPrice(originalPrice)}
            </span>
          )}
        </div>

        <button
          className="product-card__button"
          disabled={!inStock}
          onClick={() => onAddToCart?.(product)}
        >
          {inStock ? 'Add to Cart' : 'Unavailable'}
        </button>
      </div>
    </div>
  );
}

export default ProductCard;
```

