# Primary Button Component

**`Button.tsx`**

```tsx
import { forwardRef } from 'react';
import './Button.css';

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Stretch the button to fill its container. */
  fullWidth?: boolean;
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    { fullWidth = false, className = '', type = 'button', children, ...rest },
    ref,
  ) {
    const classes = ['btn', fullWidth && 'btn--full', className]
      .filter(Boolean)
      .join(' ');

    return (
      <button ref={ref} type={type} className={classes} {...rest}>
        {children}
      </button>
    );
  },
);
```

**`Button.css`**

```css
.btn {
  --btn-bg: #2563eb;
  --btn-bg-hover: #1d4ed8;
  --btn-bg-active: #1e40af;
  --btn-ring: rgba(37, 99, 235, 0.4);

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;

  padding: 0.625rem 1.25rem;
  font: inherit;
  font-size: 0.9375rem;
  font-weight: 600;
