## `PrimaryButton.tsx`

```tsx
import React from 'react';
import './Button.css';

type PrimaryButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  /** Stretch the button to fill its container. */
  fullWidth?: boolean;
};

export function PrimaryButton({
  children,
  fullWidth = false,
  className = '',
  type = 'button',
  ...rest
}: PrimaryButtonProps) {
  const classes = [
    'btn-primary',
    fullWidth ? 'btn-primary--full' : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <button type={type} className={classes} {...rest}>
      {children}
    </button>
  );
}
```

