const formatPrice = (value, currency, locale) =>
  new Intl.NumberFormat(locale, { style: "currency", currency }).format(value);

export default function ProductCard({
  image,
  title,
  price,
  currency = "USD",
  locale = "en-US",
  description,
  badge,
  onAddToCart,
}) {
