**Usage**

```jsx
import { useState } from "react";
import Modal from "./Modal";

export default function App() {
  const [open, setOpen] = useState(false);

  return (
    <>
      <button onClick={() => setOpen(true)}>Open modal</button>

      <Modal
        isOpen={open}
        onClose={() => setOpen(false)}
        title="Delete project"
        footer={
          <>
            <button onClick={() => setOpen(false)}>Cancel</button>
            <button onClick={() => setOpen(false)}>Delete</button>
          </>
        }
      >
        <p>This action cannot be undone. Are you sure?</p>
      </Modal>
    </>
  );
}
```

**How it works**

- **Portal rendering** — the modal is rendered into `document.body`, so it escapes any parent `overflow: hidden` or stacking context.
- **Backdrop click** — uses `mousedown` and checks `e.target === e.currentTarget`, so dragging from inside the panel and releasing on the backdrop won't accidentally close it.
- **Escape key** — closes the modal when `closeOnEsc` is true.
- **Focus management** — focus moves into the panel on open, is trapped inside while open, and returns to the previously focused element on close.
- **Scroll lock** — `body` overflow is hidden while open, with scrollbar-width compensation to prevent layout shift.
- **Accessibility** — `role="dialog"`, `aria-modal`, and `aria-labelledby` are wired up, and the close button has an `aria-label`.
- **Animations** — subtle fade and pop-in effects, disabled under `prefers-reduced-motion`.
---

**Optimization Tip:** You can adjust the backdrop darkness by changing the `rgba(15, 23, 42, 0.6)` value in `.modal-backdrop`, and the panel width via `max-width` in `.modal-panel`.

Here's a ready-to-use React modal component with a darkened backdrop and a centered content panel, complete with keyboard and focus handling.
```jsx
// Modal.jsx
import { useCallback, useEffect, useId, useRef } from "react";
import { createPortal } from "react-dom";
import "./Modal.css";

const FOCUSABLE = [
  "a[href]",
  "button:not([disabled])",
  "textarea:not([disabled])",
  "input:not([disabled])",
  "select:not([disabled])",
  '[tabindex]:not([tabindex="-1"])',
].join(",");

export default function Modal({
  isOpen,
  onClose,
  title,
  children,
  footer,
  size = "md", // "sm" | "md" | "lg"
  closeOnBackdropClick = true,
  closeOnEscape = true,
  showCloseButton = true,
  ariaLabel,
  className = "",
}) {
  const panelRef = useRef(null);
  const restoreFocusRef = useRef(null);
  const titleId = useId();

  const requestClose = useCallback(() => {
    onClose?.();
  }, [onClose]);

  /* ---------- Close on Escape ---------- */
  useEffect(() => {
    if (!isOpen || !closeOnEscape) return;

    const handleKeyDown = (event) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        requestClose();
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, closeOnEscape, requestClose]);

  /* ---------- Scroll lock + focus management ---------- */
  useEffect(() => {
    if (!isOpen) return;

    restoreFocusRef.current = document.activeElement;

    const { overflow, paddingRight } = document.body.style;
    const scrollbarWidth =
      window.innerWidth - document.documentElement.clientWidth;

    document.body.style.overflow = "hidden";
    if (scrollbarWidth > 0) {
      document.body.style.paddingRight = `${scrollbarWidth}px`;
    }

    // Move focus into the dialog once it has painted.
    const frame = requestAnimationFrame(() => {
      const panel = panelRef.current;
      if (!panel) return;
      const first = panel.querySelector(FOCUSABLE);
      (first ?? panel).focus({ preventScroll: true });
    });

    return () => {
      cancelAnimationFrame(frame);
      document.body.style.overflow = overflow;
      document.body.style.paddingRight = paddingRight;
      restoreFocusRef.current?.focus?.({ preventScroll: true });
    };
  }, [isOpen]);

  /* ---------- Trap Tab focus inside the panel ---------- */
  const handleKeyDown = (event) => {
    if (event.key !== "Tab") return;

    const panel = panelRef.current;
    if (!panel) return;

    const focusable = Array.from(panel.querySelectorAll(FOCUSABLE)).filter(
      (el) =>
        el.offsetWidth > 0 ||
        el.offsetHeight > 0 ||
        el === document.activeElement
    );

    if (focusable.length === 0) {
      event.preventDefault();
      panel.focus({ preventScroll: true });
      return;
    }

    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    const active = document.activeElement;
    const isInside = panel.contains(active) && active !== panel;

    if (event.shiftKey) {
      if (!isInside || active === first) {
        event.preventDefault();
        last.focus();
      }
    } else if (!isInside || active === last) {
      event.preventDefault();
      first.focus();
    }
  };

  if (!isOpen) return null;

  // mousedown (not click) so a drag that starts inside the panel
  // and ends on the backdrop doesn't close the modal.
  const handleBackdropMouseDown = (event) => {
    if (!closeOnBackdropClick) return;
    if (event.target === event.currentTarget) requestClose();
  };

  return createPortal(
    <div
      className="modal-overlay"
      onMouseDown={handleBackdropMouseDown}
      onKeyDown={handleKeyDown}
    >
      <div
        ref={panelRef}
        className={`modal-panel modal-panel--${size} ${className}`.trim()}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        aria-label={!title ? ariaLabel : undefined}
        tabIndex={-1}
      >
        {(title || showCloseButton) && (
          <header className="modal-header">
            {title && (
              <h2 id={titleId} className="modal-title">
                {title}
              </h2>
            )}

            {showCloseButton && (
              <button
                type="button"
                className="modal-close"
                onClick={requestClose}
                aria-label="Close dialog"
              >
                <svg viewBox="0 0 20 20" aria-hidden="true" focusable="false">
                  <path
                    d="M5 5l10 10M15 5L5 15"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="1.75"
                    strokeLinecap="round"
                  />
                </svg>
              </button>
            )}
          </header>
        )}

        <div className="modal-body">{children}</div>

        {footer && <footer className="modal-footer">{footer}</footer>}
      </div>
    </div>,
    document.body
  );
}
