### Modal Interaction & Accessibility

This modal handles the common edge cases so you can drop it in and focus on your content.

- **Backdrop click to close** — clicking the darkened overlay dismisses the modal, but only when the click starts and ends on the backdrop itself, so dragging from inside the panel won't accidentally close it.
- **Escape key support** — pressing Escape triggers the same close handler, and the event is stopped from bubbling further.
- **Focus management** — when the modal opens, focus moves to the first focusable element inside the panel (or the panel itself). Tab and Shift+Tab are trapped within the dialog, and focus returns to the previously active element when it closes.
- **Scroll lock** — the page behind the modal is locked from scrolling, with scrollbar width compensation to prevent layout shift.
- **Accessible markup** — the panel uses `role="dialog"`, `aria-modal="true"`, and is labelled by the title (or an `ariaLabel` fallback). The close button has an `aria-label`.
- **Responsive & motion-aware** — the panel adapts its max width via the `size` prop (`sm`, `md`, `lg`), and animations are disabled for users who prefer reduced motion.
---

**Optimization Tip:** You can adjust the backdrop color and blur by editing the `background-color` and `backdrop-filter` values in `.modal-overlay`. The panel's max width is controlled by the `size` prop and the corresponding `.modal-panel--*` classes.

Here's a ready-to-use React modal component with a darkened backdrop and centered content panel, complete with focus management and keyboard support.
```jsx
// Modal.jsx
import { useEffect, useId, useRef } from 'react';
import { createPortal } from 'react-dom';
import './Modal.css';

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

export default function Modal({
  isOpen,
  onClose,
  title,
  ariaLabel,
  children,
  footer,
}) {
  const panelRef = useRef(null);
  const backdropDownRef = useRef(false);
  const restoreFocusRef = useRef(null);
  const titleId = useId();

  // Escape to close + keep Tab focus inside the panel.
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (event) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        onClose();
        return;
      }
      if (event.key !== 'Tab') return;

      const panel = panelRef.current;
      if (!panel) return;

      const focusables = Array.from(panel.querySelectorAll(FOCUSABLE));
      if (focusables.length === 0) {
        event.preventDefault();
        panel.focus();
        return;
      }

      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      const active = document.activeElement;

      if (!panel.contains(active)) {
        event.preventDefault();
        first.focus();
      } else if (event.shiftKey && active === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  // Lock body scroll (compensating for the scrollbar so the page doesn't jump).
  useEffect(() => {
    if (!isOpen) return;

    const { body } = document;
    const prevOverflow = body.style.overflow;
    const prevPaddingRight = body.style.paddingRight;
    const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth;

    body.style.overflow = 'hidden';
    if (scrollbarWidth > 0) body.style.paddingRight = `${scrollbarWidth}px`;

    return () => {
      body.style.overflow = prevOverflow;
      body.style.paddingRight = prevPaddingRight;
    };
  }, [isOpen]);

  // Move focus in on open, restore it on close.
  useEffect(() => {
    if (!isOpen) return;

    restoreFocusRef.current = document.activeElement;
    const panel = panelRef.current;
    const target = panel?.querySelector(FOCUSABLE) ?? panel;
    target?.focus();

    return () => {
      restoreFocusRef.current?.focus?.();
    };
  }, [isOpen]);

  if (!isOpen) return null;

  return createPortal(
    <div
      className="modal-backdrop"
      // Only close when the press *starts and ends* on the backdrop itself,
      // so dragging a text selection out of the panel doesn't dismiss it.
      onMouseDown={(event) => {
        backdropDownRef.current = event.target === event.currentTarget;
      }}
      onClick={(event) => {
        if (backdropDownRef.current && event.target === event.currentTarget) {
          onClose();
        }
        backdropDownRef.current = false;
      }}
    >
      <div
        ref={panelRef}
        className="modal-panel"
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        aria-label={title ? undefined : ariaLabel}
        tabIndex={-1}
      >
        <header className="modal-header">
          {title && (
            <h2 id={titleId} className="modal-title">
              {title}
            </h2>
          )}
          <button
            type="button"
            className="modal-close"
            onClick={onClose}
            aria-label="Close dialog"
          >
            <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true" focusable="false">
              <path
                d="M1.5 1.5l13 13m0-13l-13 13"
                stroke="currentColor"
                strokeWidth="1.75"
                strokeLinecap="round"
              />
            </svg>
          </button>
        </header>

        <div className="modal-body">{children}</div>

        {footer && <footer className="modal-footer">{footer}</footer>}
      </div>
    </div>,
    document.body
  );
}
