### Modal Interaction & Accessibility

This modal handles the key interactions you'd expect from a polished dialog.

- **Backdrop click to close** – Clicking the darkened area outside the panel dismisses the modal, while clicks inside the panel are ignored.
- **Escape key support** – Pressing Escape closes the modal when the `closeOnEscape` prop is enabled.
- **Focus management** – Focus moves into the panel on open, cycles through focusable elements with Tab, and returns to the previously focused element on close.
- **Scroll locking** – The page behind the modal is prevented from scrolling while the modal is open.
- **Accessible markup** – The panel uses `role="dialog"`, `aria-modal`, and a labelled title for screen readers.
- **Smooth animations** – The backdrop fades in and the panel scales up gently, with reduced-motion support.
---

**Optimization Tip:** You can customize the panel width by editing `maxWidth` in the `panel` style object, and adjust the backdrop color via the `backgroundColor` value in the `backdrop` style.

Here's a ready-to-use React modal component with a darkened backdrop and centered content panel, including keyboard and focus handling.
```jsx
import { useEffect, useId, useRef } from "react";
import { createPortal } from "react-dom";

const FOCUSABLE =
  'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])';

export default function Modal({
  isOpen,
  onClose,
  title,
  children,
  footer,
  closeOnBackdrop = true,
}) {
  const panelRef = useRef(null);
  const previouslyFocused = useRef(null);
  const titleId = useId();

  // Keep the latest onClose without re-running the effect on every render.
  const onCloseRef = useRef(onClose);
  useEffect(() => {
    onCloseRef.current = onClose;
  });

  useEffect(() => {
    if (!isOpen) return;

    previouslyFocused.current = document.activeElement;

    const handleKeyDown = (event) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        onCloseRef.current?.();
        return;
      }

      if (event.key !== "Tab") return;

      const nodes = panelRef.current?.querySelectorAll(FOCUSABLE);
      if (!nodes || nodes.length === 0) {
        event.preventDefault();
        return;
      }

      const first = nodes[0];
      const last = nodes[nodes.length - 1];

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener("keydown", handleKeyDown);

    // Lock background scroll.
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    // Move focus into the dialog.
    const timer = window.setTimeout(() => {
      const target = panelRef.current?.querySelector(FOCUSABLE);
      (target ?? panelRef.current)?.focus();
    }, 0);

    return () => {
      document.removeEventListener("keydown", handleKeyDown);
      document.body.style.overflow = previousOverflow;
      window.clearTimeout(timer);
      previouslyFocused.current?.focus?.();
    };
  }, [isOpen]);

  if (!isOpen) return null;

  return createPortal(
    <div
      className="modal-backdrop"
      // mousedown (not click) so a drag that starts inside the panel
      // and ends on the backdrop doesn't close the modal.
      onMouseDown={(event) => {
        if (closeOnBackdrop && event.target === event.currentTarget) {
          onCloseRef.current?.();
        }
      }}
    >
      <div
        ref={panelRef}
        className="modal-panel"
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        tabIndex={-1}
      >
        <header className="modal-header">
          {title && (
            <h2 id={titleId} className="modal-title">
              {title}
            </h2>
          )}
          <button
            type="button"
            className="modal-close"
            onClick={() => onCloseRef.current?.()}
            aria-label="Close dialog"
          >
            &times;
          </button>
        </header>

        <div className="modal-body">{children}</div>

        {footer && <footer className="modal-footer">{footer}</footer>}
      </div>
    </div>,
    document.body
  );
}
