### Modal Interaction & Accessibility

This modal handles the common interaction details so you can drop it into any project.

- **Backdrop click to close** – Clicking the darkened area outside the panel dismisses the modal, but only if the click starts and ends on the backdrop itself.
- **Escape key support** – Pressing Escape closes the modal, and the event is stopped from bubbling further.
- **Focus management** – When the modal opens, focus moves into the panel; when it closes, focus returns to the element that was previously active.
- **Focus trap** – Tab and Shift+Tab cycle through focusable elements inside the panel, keeping keyboard navigation contained.
- **Scroll lock** – The page behind the modal is prevented from scrolling while the modal is open.
- **Portal rendering** – The modal is rendered into `document.body`, avoiding stacking context issues from parent containers.
---

**Optimization Tip:** You can adjust the backdrop color and panel styling by editing the `.modal-backdrop` and `.modal-panel` CSS classes. The `closeOnBackdrop` prop lets you disable backdrop-click closing if needed.

Here's a ready-to-use React modal component with a darkened backdrop and a centered content panel, including focus management and keyboard support.
```jsx
// Modal.jsx
import { useCallback, useEffect, useId, useRef } from "react";
import { createPortal } from "react-dom";

const FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  '[tabindex]:not([tabindex="-1"])',
].join(",");

export default function Modal({
  isOpen,
  onClose,
  title,
  children,
  footer,
  ariaLabel = "Dialog",
  closeOnBackdropClick = true,
  closeOnEscape = true,
  className = "",
}) {
  const panelRef = useRef(null);
  const restoreFocusRef = useRef(null);
  const mouseDownOnBackdrop = useRef(false);
  const titleId = useId();

  // --- Close on Escape -------------------------------------------------
  useEffect(() => {
    if (!isOpen || !closeOnEscape) return;

    const handleKeyDown = (event) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        onClose?.();
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, closeOnEscape, onClose]);

  // --- Lock body scroll (and compensate for the scrollbar) -------------
  useEffect(() => {
    if (!isOpen) return;

    const { overflow, paddingRight } = document.body.style;
    const scrollbarWidth =
      window.innerWidth - document.documentElement.clientWidth;

    document.body.style.overflow = "hidden";
    if (scrollbarWidth > 0) {
      document.body.style.paddingRight = `${scrollbarWidth}px`;
    }

    return () => {
      document.body.style.overflow = overflow;
      document.body.style.paddingRight = paddingRight;
    };
  }, [isOpen]);

  // --- Move focus in on open, restore it on close ----------------------
  useEffect(() => {
    if (!isOpen) return;

    restoreFocusRef.current = document.activeElement;

    const panel = panelRef.current;
    if (panel) {
      const firstFocusable = panel.querySelector(FOCUSABLE_SELECTOR);
      (firstFocusable ?? panel).focus();
    }

    return () => {
      const previous = restoreFocusRef.current;
      if (previous instanceof HTMLElement) previous.focus();
    };
  }, [isOpen]);

  // --- Trap Tab focus inside the panel ---------------------------------
  const handlePanelKeyDown = useCallback((event) => {
    if (event.key !== "Tab") return;

    const panel = panelRef.current;
    if (!panel) return;

    const focusable = Array.from(panel.querySelectorAll(FOCUSABLE_SELECTOR));
    if (focusable.length === 0) {
      event.preventDefault();
      return;
    }

    const first = focusable[0];
    const last = focusable[focusable.length - 1];

    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  }, []);

  if (!isOpen) return null;

  return createPortal(
    <div
      className="modal-backdrop"
      // Track where the press started so a text-selection drag that ends
      // on the backdrop doesn't accidentally close the modal.
      onMouseDown={(event) => {
        mouseDownOnBackdrop.current = event.target === event.currentTarget;
      }}
      onClick={(event) => {
        const startedOnBackdrop = mouseDownOnBackdrop.current;
        mouseDownOnBackdrop.current = false;

        if (
          closeOnBackdropClick &&
          startedOnBackdrop &&
          event.target === event.currentTarget
        ) {
          onClose?.();
        }
      }}
    >
      <div
        ref={panelRef}
        className={`modal-panel ${className}`.trim()}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        aria-label={title ? undefined : ariaLabel}
        tabIndex={-1}
        onKeyDown={handlePanelKeyDown}
      >
        <header className="modal-header">
          {title ? (
            <h2 id={titleId} className="modal-title">
              {title}
            </h2>
          ) : (
            <span />
          )}

          <button
            type="button"
            className="modal-close"
            onClick={onClose}
            aria-label="Close dialog"
          >
            <svg
              width="16"
              height="16"
              viewBox="0 0 16 16"
              fill="none"
              aria-hidden="true"
            >
              <path
                d="M4 4l8 8M12 4l-8 8"
                stroke="currentColor"
                strokeWidth="1.75"
                strokeLinecap="round"
              />
            </svg>
          </button>
        </header>

        <div className="modal-body">{children}</div>

        {footer && <footer className="modal-footer">{footer}</footer>}
      </div>
    </div>,
    document.body
  );
}
