### Modal Behavior & Interaction

The modal handles focus, keyboard navigation, and backdrop clicks so you don't have to wire those up yourself. Here's what's happening under the hood:

- **Backdrop click to close** — clicking anywhere outside the panel triggers `onClose`, but only if the click starts on the backdrop itself. This prevents accidental closes when dragging text from inside the panel.
- **Keyboard controls** — pressing `Escape` closes the modal, and `Tab` or `Shift+Tab` cycles focus only through focusable elements inside the panel, keeping keyboard users contained.
- **Focus restoration** — when the modal opens, focus moves to the first focusable element inside the panel. When it closes, focus returns to whatever element had it before opening.
- **Scroll lock** — the body scroll is disabled while the modal is open, with a scrollbar-width compensation to prevent page layout shift.
- **Accessibility** — the panel uses `role="dialog"`, `aria-modal="true"`, and `aria-labelledby` tied to the title for screen readers.
---

**Optimization Tip:** You can customize the backdrop color and blur by editing the `background` and `backdrop-filter` values in `.modal-backdrop`. The panel's max width is set to `480px` in `.modal-panel` — adjust that to fit wider content.

Here's a ready-to-use React modal component with a darkened backdrop and a centered content panel. It includes focus management, scroll locking, and smooth transitions.
```jsx
// Modal.jsx
import { useEffect, useId, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import './Modal.css';

/** Keep in sync with the transition duration in Modal.css */
const TRANSITION_MS = 180;

const FOCUSABLE_SELECTOR = [
  'a[href]',
  'area[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  'iframe',
  'audio[controls]',
  'video[controls]',
  '[contenteditable]:not([contenteditable="false"])',
  '[tabindex]:not([tabindex="-1"])',
].join(',');

function getFocusable(container) {
  if (!container) return [];
  return Array.from(container.querySelectorAll(FOCUSABLE_SELECTOR)).filter(
    (el) => el.getClientRects().length > 0 // visible only
  );
}

/**
 * Keeps the modal mounted for `duration` ms after `isOpen` flips to false,
 * so the exit transition has time to play.
 */
function useMountTransition(isOpen, duration) {
  const [isMounted, setIsMounted] = useState(false);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    if (isOpen) setIsMounted(true);
  }, [isOpen]);

  useEffect(() => {
    if (!isMounted) return undefined;

    if (isOpen) {
      // Wait one frame so the browser paints the "hidden" state first,
      // otherwise the enter transition is skipped.
      const raf = requestAnimationFrame(() => setIsVisible(true));
      return () => cancelAnimationFrame(raf);
    }

    setIsVisible(false);
    const timer = window.setTimeout(() => setIsMounted(false), duration);
    return () => window.clearTimeout(timer);
  }, [isOpen, isMounted, duration]);

  return { isMounted, isVisible };
}

/** Locks page scroll while the modal is mounted, without layout shift. */
function useScrollLock(locked) {
  useEffect(() => {
    if (!locked) return undefined;

    const { body, documentElement } = document;
    const previousOverflow = body.style.overflow;
    const previousPaddingRight = body.style.paddingRight;

    const scrollbarWidth = window.innerWidth - documentElement.clientWidth;
    body.style.overflow = 'hidden';

    if (scrollbarWidth > 0) {
      const current = parseFloat(window.getComputedStyle(body).paddingRight) || 0;
      body.style.paddingRight = `${current + scrollbarWidth}px`;
    }

    return () => {
      body.style.overflow = previousOverflow;
      body.style.paddingRight = previousPaddingRight;
    };
  }, [locked]);
}

export default function Modal({
  isOpen,
  onClose,
  title,
  children,
  footer,
  size = 'md', // 'sm' | 'md' | 'lg' | 'full'
  initialFocusRef,
  closeOnBackdropClick = true,
  closeOnEscape = true,
  showCloseButton = true,
  className = '',
  'aria-label': ariaLabel,
}) {
  const { isMounted, isVisible } = useMountTransition(isOpen, TRANSITION_MS);
  const panelRef = useRef(null);
  const titleId = useId();

  useScrollLock(isMounted);

  // Move focus into the dialog on open; restore it on close.
  useEffect(() => {
    if (!isMounted) return undefined;

    const previouslyFocused = document.activeElement;
    const target =
      initialFocusRef?.current ??
      getFocusable(panelRef.current)[0] ??
      panelRef.current;

    target?.focus({ preventScroll: true });

    return () => {
      if (previouslyFocused instanceof HTMLElement && previouslyFocused.isConnected) {
        previouslyFocused.focus({ preventScroll: true });
      }
    };
  }, [isMounted, initialFocusRef]);

  // Escape to close + focus trap (Tab / Shift+Tab cycle inside the panel).
  useEffect(() => {
    if (!isOpen) return undefined;

    const handleKeyDown = (event) => {
      if (event.key === 'Escape' && closeOnEscape) {
        event.preventDefault();
        onClose?.();
        return;
      }

      if (event.key !== 'Tab') return;

      const focusable = getFocusable(panelRef.current);

      if (focusable.length === 0) {
        event.preventDefault();
        panelRef.current?.focus({ preventScroll: true });
        return;
      }

      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      const active = document.activeElement;
      const isInside = panelRef.current?.contains(active);

      if (event.shiftKey && (active === first || !isInside)) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && (active === last || !isInside)) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, closeOnEscape, onClose]);

  // mousedown (not click) so a drag that starts inside the panel and ends
  // on the backdrop doesn't close the modal.
  const handleBackdropMouseDown = (event) => {
    if (!closeOnBackdropClick) return;
    if (event.target === event.currentTarget) onClose?.();
  };

  if (!isMounted) return null;

  const hasHeader = Boolean(title) || showCloseButton;

  return createPortal(
    <div
      className={`modal-overlay${isVisible ? ' modal-overlay--visible' : ''}`}
      onMouseDown={handleBackdropMouseDown}
    >
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        aria-label={title ? undefined : ariaLabel}
        tabIndex={-1}
        className={`modal-panel modal-panel--${size}${className ? ` ${className}` : ''}`}
      >
        {hasHeader && (
          <header className="modal-header">
            {title ? (
              <h2 id={titleId} className="modal-title">
                {title}
              </h2>
            ) : (
              <span />
            )}

            {showCloseButton && (
              <button
                type="button"
                className="modal-close"
                onClick={onClose}
                aria-label="Close dialog"
              >
                <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
                  <path
                    d="M4 4l8 8M12 4l-8 8"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="1.75"
                    strokeLinecap="round"
                  />
                </svg>
              </button>
            )}
          </header>
        )}

        <div className="modal-body">{children}</div>

        {footer && <footer className="modal-footer">{footer}</footer>}
      </div>
    </div>,
    document.body
  );
}
