  rightIcon?: ReactNode;
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      variant = 'primary',
      size = 'md',
      loading = false,
      fullWidth = false,
      ariaDisabled = false,
      leftIcon,
      rightIcon,
      disabled,
      className,
      children,
      onClick,
      type = 'button',
      ...rest
