# Primary Button Component

A production-ready primary action button with hover, active, focus, loading, and disabled states.

### `PrimaryButton.tsx`

```tsx
import { forwardRef, type ButtonHTMLAttributes, type ReactNode } from 'react';
import styles from './PrimaryButton.module.css';

export type PrimaryButtonProps = Omit<
  ButtonHTMLAttributes<HTMLButtonElement>,
  'type' | 'children'
> & {
  /** Visual weight of the button. */
  variant?: 'solid' | 'outline';
  size?: 'sm' | 'md' | 'lg';
  /** Shows a spinner and blocks interaction. */
  loading?: boolean;
  /** Leading icon. Inherits the button's text color. */
  icon?: ReactNode;
  /** Trailing icon (e.g. an arrow). */
  trailingIcon?: ReactNode;
  /** Stretches the button to fill its container. */
  fullWidth?: boolean;
  /** Button content. */
  children?: ReactNode;
  /** Defaults to "button" so it never submits a form by accident. */
  type?: 'button' | 'submit' | 'reset';
};

export const PrimaryButton = forwardRef<HTMLButtonElement, PrimaryButtonProps>(
  function PrimaryButton(
    {
      variant = 'solid',
      size = 'md',
      loading = false,
      icon,
      trailingIcon,
      fullWidth = false,
      disabled = false,
      type = 'button',
      className,
      children,
      ...rest
    },
    ref
  ) {
    // Loading implies disabled, but keep the DOM attribute accurate.
    const isDisabled = disabled || loading;

    const classes = [
      styles.root,
      styles[variant],
      styles[size],
      fullWidth ? styles.fullWidth : '',
      loading ? styles.loading : '',
      className ?? '',
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <button
        {...rest}
        ref={ref}
        type={type}
        className={classes}
        disabled={isDisabled}
        aria-busy={loading || undefined}
        data-loading={loading || undefined}
      >
        {loading ? <span className={styles.spinner} aria-hidden="true" /> : icon}
        {children ? <span className={styles.label}>{children}</span> : null}
        {!loading && trailingIcon}
      </button>
    );
  }
);
```

