// ProductCard.jsx
import { useState } from "react";
import "./ProductCard.css";

const currencyFormatters = new Map();

function formatPrice(amount, currency = "USD", locale = "en-US") {
  const key = `${locale}-${currency}`;
  if (!currencyFormatters.has(key)) {
    currencyFormatters.set(
      key,
      new Intl.NumberFormat(locale, { style: "currency", currency })
    );
  }
  return currencyFormatters.get(key).format(amount);
}

export default function ProductCard({
  image,
  title,
  price,
  currency = "USD",
  locale = "en-US",
  compareAtPrice = null,
  badge = null,
  onAddToCart = null,
}) {
  const [imageFailed, setImageFailed] = useState(false);
  const hasDiscount =
    compareAtPrice != null && compareAtPrice > price;

  return (
    <article className="product-card">
      <div className="product-card__media">
        {badge && <span className="product-card__badge">{badge}</span>}

        {imageFailed ? (
          <div className="product-card__placeholder" aria-hidden="true">
            🛍️
          </div>
        ) : (
          <img
            src={image}
            alt={title}
            loading="lazy"
            className="product-card__image"
            onError={() => setImageFailed(true)}
          />
        )}
      </div>

      <div className="product-card__body">
        <h3 className="product-card__title" title={title}>
          {title}
        </h3>

        <div className="product-card__pricing">
          <span className="product-card__price">
            {formatPrice(price, currency, locale)}
          </span>

          {hasDiscount && (
            <>
              <span className="product-card__compare-price">
                {formatPrice(compareAtPrice, currency, locale)}
              </span>
              <span className="product-card__discount">
                {Math.round((1 - price / compareAtPrice) * 100)}% off
              </span>
            </>
          )}
        </div>

        {onAddToCart && (
          <button
            type="button"
            className="product-card__button"
            onClick={() => onAddToCart({ title, price, image })}
          >
            Add to cart
          </button>
        )}
      </div>
    </article>
  );
}
