## `ProductCard.tsx`

```tsx
import { useState } from 'react';
import styles from './ProductCard.module.css';

export type Product = {
  id: string;
  title: string;
  price: number;
  /** Optional "was" price for showing a discount */
  compareAtPrice?: number;
  imageUrl: string;
  imageAlt?: string;
  href?: string;
  badge?: string;
};

type Props = {
  product: Product;
  currency?: string;
  locale?: string;
  onSelect?: (product: Product) => void;
};

export default function ProductCard({
  product,
  currency = 'USD',
  locale = 'en-US',
  onSelect,
}: Props) {
  const [imageFailed, setImageFailed] = useState(false);

  const formatter = new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
  });

  const hasDiscount =
    product.compareAtPrice != null && product.compareAtPrice > product.price;

  const discountPercent = hasDiscount
    ? Math.round(
        ((product.compareAtPrice! - product.price) / product.compareAtPrice!) * 100
      )
    : 0;

  const handleClick = () => onSelect?.(product);

  return (
    <article className={styles.card}>
      <div className={styles.media}>
        {product.badge && <span className={styles.badge}>{product.badge}</span>}
        {hasDiscount && (
          <span className={styles.discount}>-{discountPercent}%</span>
        )}

        {imageFailed ? (
          <div className={styles.placeholder} aria-hidden="true">
            <span>No image</span>
          </div>
        ) : (
          <img
            src={product.imageUrl}
            alt={product.imageAlt ?? product.title}
            loading="lazy"
            className={styles.image}
            onError={() => setImageFailed(true)}
          />
        )}
      </div>

      <div className={styles.body}>
        <h3 className={styles.title}>{product.title}</h3>

        <div className={styles.priceRow}>
          <span className={styles.price}>{formatter.format(product.price)}</span>
          {hasDiscount && (
            <span className={styles.compareAt}>
              {formatter.format(product.compareAtPrice!)}
            </span>
          )}
        </div>

        {product.href ? (
          <a className={styles.action} href={product.href}>
            View product
          </a>
        ) : (
          <button type="button" className={styles.action} onClick={handleClick}>
            Add to cart
          </button>
        )}
      </div>
    </article>
  );
}
```

