Here's a reusable product card component with TypeScript props, price formatting, an optional discount badge, and an image-error fallback.

## `ProductCard.tsx`

```tsx
import { useState } from 'react';
import './ProductCard.css';

export interface ProductCardProps {
  /** URL of the product image */
  image: string;
  /** Product name */
  title: string;
  /** Current price in major currency units (e.g. 19.99) */
  price: number;
  /** ISO currency code — defaults to USD */
  currency?: string;
  /** Optional "was" price; when present, a discount badge is shown */
  originalPrice?: number;
  /** Optional label rendered in the top-left corner (e.g. "New", "-20%") */
  badge?: string;
  /** Alt text for the image; falls back to the title */
  imageAlt?: string;
  /** Optional click handler — makes the card interactive */
  onClick?: () => void;
  /** Extra class names for the wrapper */
  className?: string;
}

const formatPrice = (value: number, currency: string) =>
  new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
  }).format(value);

export function ProductCard({
  image,
  title,
  price,
  currency = 'USD',
  originalPrice,
  badge,
  imageAlt,
  onClick,
  className = '',
}: ProductCardProps) {
  const [imageFailed, setImageFailed] = useState(false);

  const hasDiscount =
    typeof originalPrice === 'number' && originalPrice > price;
  const discountPercent = hasDiscount
    ? Math.round(((originalPrice! - price) / originalPrice!) * 100)
    : 0;

  const Wrapper = onClick ? 'button' : 'article';

  return (
    <Wrapper
      className={`product-card ${onClick ? 'product-card--clickable' : ''} ${className}`}
      onClick={onClick}
      {...(onClick ? { type: 'button' as const } : {})}
    >
      <div className="product-card__media">
        {imageFailed ? (
          <div className="product-card__placeholder" aria-hidden="true">
            🖼
          </div>
        ) : (
          <img
            src={image}
            alt={imageAlt ?? title}
            loading="lazy"
            className="product-card__image"
            onError={() => setImageFailed(true)}
          />
        )}

        {(badge || hasDiscount) && (
          <span className="product-card__badge">
            {badge ?? `-${discountPercent}%`}
          </span>
        )}
      </div>

      <div className="product-card__body">
        <h3 className="product-card__title" title={title}>
          {title}
        </h3>

        <div className="product-card__price">
          <span className="product-card__price-current">
            {formatPrice(price, currency)}
          </span>
          {hasDiscount && (
            <span className="product-card__price-original">
              {formatPrice(originalPrice!, currency)}
            </span>
          )}
        </div>
      </div>
    </Wrapper>
  );
}

export default ProductCard;
```

