## `ProductCard.tsx`

```tsx
import { useState } from 'react';
import './ProductCard.css';

export interface ProductCardProps {
  /** URL of the product image */
  image: string;
  /** Alt text for the image (defaults to the title) */
  imageAlt?: string;
  title: string;
  /** Current price in the smallest currency unit (e.g. 19.99) */
  price: number;
  /** Optional "was" price — a discount badge is shown when provided */
  originalPrice?: number;
  currency?: string;
  locale?: string;
  /** Optional label rendered in the top-left corner, e.g. "New" or "-20%" */
  badge?: string;
  /** Optional click handler for the add-to-cart button */
  onAddToCart?: (product: { title: string; price: number }) => void;
}

export function ProductCard({
  image,
  imageAlt,
  title,
  price,
  originalPrice,
  currency = 'USD',
  locale = 'en-US',
  badge,
  onAddToCart,
}: ProductCardProps) {
  const [imageFailed, setImageFailed] = useState(false);
  const [added, setAdded] = useState(false);

  const formatPrice = (value: number) =>
    new Intl.NumberFormat(locale, { style: 'currency', currency }).format(value);

  const hasDiscount = originalPrice != null && originalPrice > price;
  const discountPercent = hasDiscount
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : 0;

  const handleAddToCart = () => {
    onAddToCart?.({ title, price });
    setAdded(true);
    window.setTimeout(() => setAdded(false), 1500);
  };

  return (
    <article className="product-card">
      <div className="product-card__media">
        {badge && <span className="product-card__badge">{badge}</span>}

        {imageFailed ? (
          <div className="product-card__placeholder" aria-hidden="true">
            🖼
          </div>
        ) : (
          <img
            className="product-card__image"
            src={image}
            alt={imageAlt ?? title}
            loading="lazy"
            onError={() => setImageFailed(true)}
          />
        )}
      </div>

      <div className="product-card__body">
        <h3 className="product-card__title" title={title}>
          {title}
        </h3>

        <div className="product-card__pricing">
          <span className="product-card__price">{formatPrice(price)}</span>
          {hasDiscount && (
            <>
              <span className="product-card__original-price">
                {formatPrice(originalPrice)}
              </span>
              <span className="product-card__discount">-{discountPercent}%</span>
            </>
          )}
        </div>

        {onAddToCart && (
          <button
            type="button"
            className="product-card__button"
            onClick={handleAddToCart}
          >
            {added ? 'Added ✓' : 'Add to cart'}
          </button>
        )}
      </div>
    </article>
  );
}

export default ProductCard;
```

