  image: { src: string; alt: string };
  title: string;
  /** Price in the smallest currency unit (e.g. 19.99 for $19.99) */
  price: number;
  currency?: string;
  /** Optional "was" price — renders a strikethrough and a discount badge */
  originalPrice?: number;
  /** Optional label above the image (e.g. "New", "Sale") */
  badge?: ReactNode;
  /** Optional content below the card (e.g. an "Add to cart" button) */
  footer?: ReactNode;
  /** Makes the card clickable; omit for a static card */
  onSelect?: () => void;
}

function formatPrice(value: number, currency: string) {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
  }).format(value);
}

export function ProductCard({
  image,
  title,
  price,
  currency = 'USD',
  originalPrice,
  badge,
  footer,
  onSelect,
}: ProductCardProps) {
  const hasDiscount =
    typeof originalPrice === 'number' && originalPrice > price;

  const discountPercent = hasDiscount
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : 0;

  return (
    <article className={styles.card}>
      <div className={styles.media}>
        {badge && <span className={styles.badge}>{badge}</span>}
        <img
          className={styles.image}
          src={image.src}
          alt={image.alt}
          loading="lazy"
          decoding="async"
        />
      </div>

      <div className={styles.body}>
        <h3 className={styles.title}>{title}</h3>

        <p className={styles.priceRow}>
          <span className={styles.price} data-testid="product-price">
            {formatPrice(price, currency)}
          </span>
          {hasDiscount && (
            <>
              <s className={styles.originalPrice}>
                {formatPrice(originalPrice, currency)}
              </s>
              <span className={styles.discount}>-{discountPercent}%</span>
            </>
          )}
        </p>
      </div>

      {footer && <div className={styles.footer}>{footer}</div>}

      {onSelect && (
        <button
          type="button"
          className={styles.overlayButton}
          onClick={onSelect}
          aria-label={`View ${title}`}
        />
      )}
    </article>
  );
}
```

