## `ProductCard.tsx`

```tsx
import { useState } from "react";
import "./ProductCard.css";

export interface Product {
  id: string;
  title: string;
  price: number;
  imageUrl: string;
  currency?: string;
  badge?: string;
  rating?: number;
  description?: string;
}

interface ProductCardProps {
  product: Product;
  onAddToCart?: (product: Product) => void;
}

export default function ProductCard({ product, onAddToCart }: ProductCardProps) {
  const [added, setAdded] = useState(false);
  const { title, price, imageUrl, currency = "USD", badge, rating, description } = product;

  const formattedPrice = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
  }).format(price);

  const handleAdd = () => {
    onAddToCart?.(product);
    setAdded(true);
    setTimeout(() => setAdded(false), 1500);
  };

  return (
    <article className="product-card">
      <div className="product-card__media">
        <img
          src={imageUrl}
          alt={title}
          loading="lazy"
          className="product-card__image"
        />
        {badge && <span className="product-card__badge">{badge}</span>}
      </div>

      <div className="product-card__body">
        <h3 className="product-card__title">{title}</h3>

        {rating != null && (
          <p className="product-card__rating" aria-label={`Rated ${rating} out of 5`}>
            {"★".repeat(Math.round(rating))}
            <span className="product-card__rating-value">{rating.toFixed(1)}</span>
          </p>
        )}

        {description && (
          <p className="product-card__description">{description}</p>
        )}

        <p className="product-card__price">{formattedPrice}</p>

        <button
          type="button"
          className="product-card__button"
          onClick={handleAdd}
          disabled={added}
        >
          {added ? "Added ✓" : "Add to cart"}
        </button>
      </div>
    </article>
  );
}
```

