Here's a reusable `ProductCard` component with typed props, an optional discount badge, and an add-to-cart action.

```tsx
// ProductCard.tsx
import { useState } from "react";

export interface ProductCardProps {
  image: string;
  imageAlt?: string;
  title: string;
  price: number;
  originalPrice?: number;
  currency?: string;
  description?: string;
  inStock?: boolean;
  onAddToCart?: (product: { title: string; price: number }) => void;
}

export default function ProductCard({
  image,
  imageAlt,
  title,
  price,
  originalPrice,
  currency = "USD",
  description,
  inStock = true,
  onAddToCart,
}: ProductCardProps) {
  const [added, setAdded] = useState(false);
  const hasDiscount = originalPrice != null && originalPrice > price;
  const discountPercent = hasDiscount
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : 0;

  const formatPrice = (value: number) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency }).format(value);

  const handleAddToCart = () => {
    onAddToCart?.({ title, price });
    setAdded(true);
    setTimeout(() => setAdded(false), 1500);
  };

  return (
    <article className="flex flex-col overflow-hidden rounded-xl border border-gray-200 bg-white shadow-sm transition hover:shadow-md">
      <div className="relative aspect-square w-full overflow-hidden bg-gray-100">
        <img
          src={image}
          alt={imageAlt ?? title}
          loading="lazy"
          className="h-full w-full object-cover transition duration-300 hover:scale-105"
        />
        {hasDiscount && (
          <span className="absolute left-2 top-2 rounded-full bg-red-600 px-2 py-1 text-xs font-semibold text-white">
            -{discountPercent}%
          </span>
        )}
        {!inStock && (
          <span className="absolute inset-0 flex items-center justify-center bg-white/70 text-sm font-medium text-gray-700">
            Out of stock
          </span>
        )}
      </div>

      <div className="flex flex-1 flex-col gap-2 p-4">
        <h3 className="text-base font-semibold text-gray-900 line-clamp-2">{title}</h3>

        {description && (
          <p className="text-sm text-gray-500 line-clamp-2">{description}</p>
        )}

        <div className="mt-auto flex items-baseline gap-2 pt-2">
          <span className="text-lg font-bold text-gray-900">{formatPrice(price)}</span>
          {hasDiscount && (
            <span className="text-sm text-gray-400 line-through">
              {formatPrice(originalPrice)}
            </span>
          )}
        </div>

        <button
          type="button"
          onClick={handleAddToCart}
          disabled={!inStock}
          className="mt-2 w-full rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-gray-300"
        >
          {added ? "Added ✓" : inStock ? "Add to cart" : "Unavailable"}
        </button>
      </div>
    </article>
  );
}
```

