## Notes

- **Backdrop click** uses `onMouseDown` with a `target === currentTarget` check, so a text selection that starts inside the panel and ends on the backdrop won't close it.
- **Focus management**: focus moves to the first focusable element on open and returns to the trigger on close; Tab cycles within the panel.
- **Scroll lock** compensates for the scrollbar width to prevent layout shift.
- **Accessibility**: `role="dialog"`, `aria-modal="true"`, `aria-labelledby` wired to the title via `useId`, and a labelled close button.
- For a native `<dialog>` element instead, swap the portal for `showModal()` — it gives you the top layer and backdrop for free, but requires manual focus-trap and scroll-lock handling.

# React Modal Component

A production-ready modal with a darkened backdrop, centered panel, keyboard support, and accessibility features.

```tsx
// Modal.tsx
import { useEffect, useRef, type ReactNode } from "react";
import { createPortal } from "react-dom";

type ModalProps = {
  /** Whether the modal is visible */
  isOpen: boolean;
  /** Called when the user requests to close (ESC key, backdrop click, or close button) */
  onClose: () => void;
  /** Accessible label for the dialog */
  title?: string;
  /** Modal content */
  children: ReactNode;
  /** Hide the default header/close button */
  hideHeader?: boolean;
  /** Disable closing via backdrop click or ESC */
  dismissible?: boolean;
};

export function Modal({
  isOpen,
  onClose,
  title,
  children,
  hideHeader = false,
  dismissible = true,
}: ModalProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  const previouslyFocused = useRef<HTMLElement | null>(null);

  // Lock body scroll while open
  useEffect(() => {
    if (!isOpen) return;
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = originalOverflow;
    };
  }, [isOpen]);

  // Handle ESC key, focus management, and restore focus on close
  useEffect(() => {
    if (!isOpen) return;

    previouslyFocused.current = document.activeElement as HTMLElement;
    panelRef.current?.focus();

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape" && dismissible) {
        event.stopPropagation();
        onClose();
      }

      // Trap focus inside the modal
      if (event.key === "Tab" && panelRef.current) {
        const focusable = panelRef.current.querySelectorAll<HTMLElement>(
          'a[href], button:not([disabled]), textarea, input, select, [tabindex]:not([tabindex="-1"])'
        );
        if (focusable.length === 0) return;

        const first = focusable[0];
        const last = focusable[focusable.length - 1];

        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault();
          last.focus();
        } else if (!event.shiftKey && document.activeElement === last) {
          event.preventDefault();
          first.focus();
        }
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
      previouslyFocused.current?.focus();
    };
  }, [isOpen, dismissible, onClose]);

  if (!isOpen) return null;

  return createPortal(
    <div
      className="modal-backdrop"
      onMouseDown={(e) => {
        // Only close if the mousedown started on the backdrop itself
        if (e.target === e.currentTarget && dismissible) {
          onClose();
        }
      }}
    >
      <div
        ref={panelRef}
        className="modal-panel"
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? "modal-title" : undefined}
        tabIndex={-1}
      >
        {!hideHeader && (
          <header className="modal-header">
            {title && (
              <h2 id="modal-title" className="modal-title">
                {title}
              </h2>
            )}
            {dismissible && (
              <button
                type="button"
                className="modal-close"
                onClick={onClose}
                aria-label="Close modal"
              >
                &times;
              </button>
            )}
          </header>
        )}
        <div className="modal-content">{children}</div>
      </div>
    </div>,
    document.body
  );
}
