## Key features

| Feature | Details |
|---|---|
| **Backdrop** | Fixed overlay with `rgba(0,0,0,0.6)` darkening, centered via flexbox |
| **Portal** | Rendered into `document.body` to avoid stacking/overflow issues |
| **Scroll lock** | Body scroll is disabled while open and restored on close |
| **Keyboard** | `Esc` closes; `Tab` is trapped inside the panel |
| **Focus** | Moves to the panel on open, restores to the trigger on close |
| **Backdrop click** | Closes only when the click starts on the backdrop (not inside) |
| **Accessibility** | `role="dialog"`, `aria-modal`, `aria-labelledby`, labeled close button |

**Note:** If you use Tailwind CSS, you can skip the CSS file and replace the class names with utility classes (e.g. `fixed inset-0 bg-black/60 flex items-center justify-center`).

Below is a production‑ready modal: portal‑rendered, backdrop‑dimmed, focus‑trapped, Escape/backdrop dismissible, scroll‑locked, and accessible.

## `Modal.tsx`

```tsx
import {
  useCallback,
  useEffect,
  useId,
  useRef,
  type ReactNode,
} from 'react';
import { createPortal } from 'react-dom';
import './Modal.css';

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl';

export interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: ReactNode;
  description?: ReactNode;
  children: ReactNode;
  footer?: ReactNode;
  size?: ModalSize;
  /** Clicking the dimmed backdrop closes the modal. */
  closeOnBackdropClick?: boolean;
  /** Pressing Escape closes the modal. */
  closeOnEscape?: boolean;
  showCloseButton?: boolean;
  className?: string;
}

const FOCUSABLE_SELECTOR = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
].join(',');

function getFocusable(container: HTMLElement): HTMLElement[] {
  return Array.from(
    container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR),
  ).filter((el) => el.offsetParent !== null || el === document.activeElement);
}

export function Modal({
  isOpen,
  onClose,
  title,
  description,
  children,
  footer,
  size = 'md',
  closeOnBackdropClick = true,
  closeOnEscape = true,
  showCloseButton = true,
  className = '',
}: ModalProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  const titleId = useId();
  const descriptionId = useId();

  // Keep the latest callback without re-running the open/close effect.
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;

  const handleClose = useCallback(() => onCloseRef.current(), []);

  useEffect(() => {
    if (!isOpen) return;

    const previouslyFocused = document.activeElement as HTMLElement | null;
    const { body } = document;

    // Lock scrolling without causing a layout shift from the scrollbar.
    const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth;
    const prevOverflow = body.style.overflow;
    const prevPaddingRight = body.style.paddingRight;
    body.style.overflow = 'hidden';
    if (scrollbarWidth > 0) body.style.paddingRight = `${scrollbarWidth}px`;

    // Move focus into the dialog once it has painted.
    const raf = requestAnimationFrame(() => {
      const panel = panelRef.current;
      if (!panel) return;
      const focusables = getFocusable(panel);
      (focusables[0] ?? panel).focus();
    });

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && closeOnEscape) {
        event.preventDefault();
        event.stopPropagation();
        handleClose();
        return;
      }

      if (event.key !== 'Tab') return;

      const panel = panelRef.current;
      if (!panel) return;

      const focusables = getFocusable(panel);
      if (focusables.length === 0) {
        event.preventDefault();
        panel.focus();
        return;
      }

      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      const active = document.activeElement;

      if (event.shiftKey && (active === first || !panel.contains(active))) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && (active === last || !panel.contains(active))) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener('keydown', onKeyDown, true);

    return () => {
      cancelAnimationFrame(raf);
      document.removeEventListener('keydown', onKeyDown, true);
      body.style.overflow = prevOverflow;
      body.style.paddingRight = prevPaddingRight;
      previouslyFocused?.focus?.();
    };
  }, [isOpen, closeOnEscape, handleClose]);

  if (!isOpen) return null;
  if (typeof document === 'undefined') return null; // SSR safety

  return createPortal(
    <div
      className="modal-backdrop"
      data-testid="modal-backdrop"
      onMouseDown={(event) => {
        // Only dismiss when the press *starts* on the backdrop itself.
        if (closeOnBackdropClick && event.target === event.currentTarget) {
          handleClose();
        }
      }}
    >
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        aria-describedby={description ? descriptionId : undefined}
        tabIndex={-1}
        className={`modal-panel modal-panel--${size} ${className}`}
      >
        {(title || showCloseButton) && (
          <header className="modal-header">
            <div className="modal-heading">
              {title && (
                <h2 id={titleId} className="modal-title">
                  {title}
                </h2>
              )}
              {description && (
                <p id={descriptionId} className="modal-description">
                  {description}
                </p>
              )}
            </div>
            {showCloseButton && (
              <button
                type="button"
                className="modal-close"
                onClick={handleClose}
                aria-label="Close dialog"
              >
                &times;
              </button>
            )}
          </header>
        )}

        <div className="modal-body">{children}</div>

        {footer && <footer className="modal-footer">{footer}</footer>}
      </div>
    </div>,
    document.body,
  );
}

export default Modal;
```

