# React Modal Component

A self-contained, accessible modal: dark backdrop, centered panel, escape-to-close, focus trap, scroll lock, and body-scroll restoration.

## `Modal.jsx`

```jsx
import { useCallback, useEffect, useId, useRef } from "react";
import { createPortal } from "react-dom";

const FOCUSABLE = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled]):not([type='hidden'])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  "[tabindex]:not([tabindex='-1'])",
].join(",");

/**
 * @param {object} props
 * @param {boolean} props.isOpen
 * @param {() => void} props.onClose
 * @param {string} [props.title]
 * @param {React.ReactNode} props.children
 * @param {React.ReactNode} [props.footer]
 * @param {boolean} [props.closeOnBackdropClick]
 * @param {boolean} [props.closeOnEscape]
 * @param {boolean} [props.showCloseButton]
 */
export default function Modal({
  isOpen,
  onClose,
  title,
  children,
  footer,
  closeOnBackdropClick = true,
  closeOnEscape = true,
  showCloseButton = true,
}) {
  const panelRef = useRef(null);
  const restoreFocusRef = useRef(null);
  const titleId = useId();

  // Lock body scroll + restore focus to the trigger on unmount.
  useEffect(() => {
    if (!isOpen) return;

    restoreFocusRef.current = document.activeElement;

    const { overflow, paddingRight } = document.body.style;
    // Compensate for the scrollbar so the page doesn't shift horizontally.
    const scrollbar = window.innerWidth - document.documentElement.clientWidth;
    document.body.style.overflow = "hidden";
    if (scrollbar > 0) document.body.style.paddingRight = `${scrollbar}px`;

    return () => {
      document.body.style.overflow = overflow;
      document.body.style.paddingRight = paddingRight;
      restoreFocusRef.current?.focus?.();
    };
  }, [isOpen]);

  // Move focus into the panel when it opens.
  useEffect(() => {
    if (!isOpen || !panelRef.current) return;
    const first = panelRef.current.querySelector(FOCUSABLE);
    (first ?? panelRef.current).focus();
  }, [isOpen]);

  // Keyboard handling: Escape closes, Tab is trapped inside the panel.
  useEffect(() => {
    if (!isOpen) return;

    const onKeyDown = (event) => {
      if (event.key === "Escape" && closeOnEscape) {
        event.stopPropagation();
        onClose();
        return;
      }

      if (event.key !== "Tab" || !panelRef.current) return;

      const focusable = Array.from(
        panelRef.current.querySelectorAll(FOCUSABLE)
      ).filter((el) => el.offsetParent !== null);

      if (focusable.length === 0) {
        event.preventDefault();
        panelRef.current.focus();
        return;
      }

      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      const active = document.activeElement;

      if (!panelRef.current.contains(active)) {
        event.preventDefault();
        (event.shiftKey ? last : first).focus();
      } else if (event.shiftKey && active === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [isOpen, onClose, closeOnEscape]);

  // Only close if the mousedown *started* on the backdrop (avoids the
  // "drag from inside the panel and release on the backdrop" false positive).
  const handleBackdropMouseDown = useCallback(
    (event) => {
      if (closeOnBackdropClick && event.target === event.currentTarget) {
        onClose();
      }
    },
    [closeOnBackdropClick, onClose]
  );

  if (!isOpen) return null;

  return createPortal(
    <>
      <style>{`
        @keyframes modal-fade { from { opacity: 0 } to { opacity: 1 } }
        @keyframes modal-pop {
          from { opacity: 0; transform: translateY(8px) scale(.97) }
          to   { opacity: 1; transform: translateY(0) scale(1) }
        }
        .modal-backdrop { animation: modal-fade .15s ease-out; }
        .modal-panel   { animation: modal-pop .18s cubic-bezier(.2,.8,.3,1); }
        @media (prefers-reduced-motion: reduce) {
          .modal-backdrop, .modal-panel { animation: none; }
        }
      `}</style>

      <div
        className="modal-backdrop"
        onMouseDown={handleBackdropMouseDown}
        style={{
          position: "fixed",
          inset: 0,
          zIndex: 1000,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: "1rem",
          backgroundColor: "rgba(0, 0, 0, 0.6)",
          backdropFilter: "blur(2px)",
        }}
      >
        <div
          ref={panelRef}
          role="dialog"
          aria-modal="true"
          aria-labelledby={title ? titleId : undefined}
          tabIndex={-1}
          className="modal-panel"
          style={{
            position: "relative",
            width: "100%",
            maxWidth: "32rem",
            maxHeight: "90vh",
            display: "flex",
            flexDirection: "column",
            backgroundColor: "#fff",
            color: "#111",
            borderRadius: "12px",
            boxShadow: "0 20px 50px rgba(0, 0, 0, 0.35)",
            outline: "none",
          }}
        >
          {title && (
            <header
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                gap: "1rem",
                padding: "1.25rem 1.5rem",
                borderBottom: "1px solid #e5e7eb",
              }}
            >
              <h2 id={titleId} style={{ margin: 0, fontSize: "1.125rem" }}>
                {title}
              </h2>
              {showCloseButton && (
                <button
                  type="button"
                  onClick={onClose}
                  aria-label="Close dialog"
                  style={{
                    border: "none",
                    background: "transparent",
                    fontSize: "1.5rem",
                    lineHeight: 1,
                    cursor: "pointer",
                    color: "#6b7280",
                    padding: "0.25rem",
                    borderRadius: "6px",
                  }}
                >
                  &times;
                </button>
              )}
            </header>
          )}

          <div style={{ padding: "1.5rem", overflowY: "auto" }}>{children}</div>

          {footer && (
            <footer
              style={{
                padding: "1rem 1.5rem",
                borderTop: "1px solid #e5e7eb",
                display: "flex",
                justifyContent: "flex-end",
                gap: "0.5rem",
              }}
            >
              {footer}
            </footer>
          )}
        </div>
      </div>
    </>,
    document.body
  );
}
