## What it handles

| Concern | Behavior |
|---|---|
| Backdrop | `rgba(0,0,0,.6)` overlay, click to dismiss (mousedown-based to avoid false positives) |
| Positioning | Fixed overlay, flex-centered panel, `max-height: 90vh` with internal scroll |
| Escape key | Closes the modal, stops propagation so parent dialogs don't also close |
| Focus | Moves into the panel on open, cycles with Tab/Shift+Tab, returns to the trigger on close |
| Scroll lock | `body { overflow: hidden }` + scrollbar-width compensation to prevent layout shift |
| Semantics | `role="dialog"`, `aria-modal="true"`, `aria-labelledby` pointing at the title |

## Notes / variations

- **Tailwind or CSS Modules:** delete the inline `style` objects and the `<style>` tag, and use utility classes instead — the structure stays the same.
- **Dark mode:** add `backgroundColor: "var(--surface)"` / `color: "var(--text)"` to the panel.
- **Custom sizes:** expose a `size` prop (`"sm" | "md" | "lg"`) that maps to `maxWidth`.
- **Animations:** the keyframes respect `prefers-reduced-motion`.
- **Server-side rendering:** `createPortal` touches `document.body`, so render the modal only after mount (e.g. gate on a `useMounted` hook) if you use Next.js.

# React Modal Component

A production-ready modal with a darkened backdrop, centered panel, focus trapping, scroll locking, and keyboard support.

## `Modal.tsx`

```tsx
import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import "./Modal.css";

export type ModalSize = "sm" | "md" | "lg" | "xl";

export interface ModalProps {
  /** Whether the modal is visible. */
  isOpen: boolean;
  /** Called when the modal requests to be closed (Esc, backdrop, X button). */
  onClose: () => void;
  title?: ReactNode;
  children: ReactNode;
  footer?: ReactNode;
  size?: ModalSize;
  /** Close when the darkened backdrop is clicked. Default: true. */
  closeOnBackdropClick?: boolean;
  /** Close when Escape is pressed. Default: true. */
  closeOnEscape?: boolean;
  /** Render a close button in the header. Default: true. */
  showCloseButton?: boolean;
  className?: string;
}

const FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled]):not([type='hidden'])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  "[tabindex]:not([tabindex='-1'])",
].join(",");

const ANIMATION_MS = 200;

export function Modal({
  isOpen,
  onClose,
  title,
  children,
  footer,
  size = "md",
  closeOnBackdropClick = true,
  closeOnEscape = true,
  showCloseButton = true,
  className = "",
}: ModalProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  const previouslyFocused = useRef<HTMLElement | null>(null);
  const titleId = useId();

  // `rendered` keeps the DOM mounted during the exit animation.
  const [rendered, setRendered] = useState(isOpen);
  const [visible, setVisible] = useState(false);

  // --- Mount / unmount with transition -------------------------------------
  useEffect(() => {
    if (isOpen) {
      setRendered(true);
      const raf = requestAnimationFrame(() => setVisible(true));
      return () => cancelAnimationFrame(raf);
    }
    setVisible(false);
    const timer = setTimeout(() => setRendered(false), ANIMATION_MS);
    return () => clearTimeout(timer);
  }, [isOpen]);

  // --- Lock body scroll (and compensate for the scrollbar) -----------------
  useEffect(() => {
    if (!rendered) return;
    const { body } = document;
    const prevOverflow = body.style.overflow;
    const prevPadding = body.style.paddingRight;
    const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth;

    body.style.overflow = "hidden";
    if (scrollbarWidth > 0) body.style.paddingRight = `${scrollbarWidth}px`;

    return () => {
      body.style.overflow = prevOverflow;
      body.style.paddingRight = prevPadding;
    };
  }, [rendered]);

  // --- Focus management: move in on open, restore on close ------------------
  useEffect(() => {
    if (!rendered) return;
    previouslyFocused.current = document.activeElement as HTMLElement | null;

    const focusFirst = () => {
      const panel = panelRef.current;
      if (!panel) return;
      const focusable = panel.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR);
      (focusable[0] ?? panel).focus();
    };
    const raf = requestAnimationFrame(focusFirst);

    return () => {
      cancelAnimationFrame(raf);
      previouslyFocused.current?.focus?.();
    };
  }, [rendered]);

  // --- Keyboard: Escape + Tab focus trap -----------------------------------
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (event.key === "Escape" && closeOnEscape) {
        event.stopPropagation();
        onClose();
        return;
      }

      if (event.key !== "Tab") return;

      const panel = panelRef.current;
      if (!panel) return;

      const focusable = Array.from(
        panel.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR),
      ).filter((el) => el.offsetParent !== null);

      if (focusable.length === 0) {
        event.preventDefault();
        panel.focus();
        return;
      }

      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      const active = document.activeElement;

      if (event.shiftKey && (active === first || active === panel)) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
    },
    [closeOnEscape, onClose],
  );

  useEffect(() => {
    if (!rendered) return;
    document.addEventListener("keydown", handleKeyDown, true);
    return () => document.removeEventListener("keydown", handleKeyDown, true);
  }, [rendered, handleKeyDown]);

  // --- Keep focus inside if it escapes (e.g. browser chrome) ----------------
  useEffect(() => {
    if (!rendered) return;
    const onFocusIn = (event: FocusEvent) => {
      const panel = panelRef.current;
      if (panel && !panel.contains(event.target as Node)) {
        panel.focus();
      }
    };
    document.addEventListener("focusin", onFocusIn);
    return () => document.removeEventListener("focusin", onFocusIn);
  }, [rendered]);

  const handleBackdropMouseDown = (event: React.MouseEvent<HTMLDivElement>) => {
    // Only close if the press *started* on the backdrop itself.
    if (closeOnBackdropClick && event.target === event.currentTarget) {
      onClose();
    }
  };

  if (!rendered) return null;

  return createPortal(
    <div
      className={`modal-overlay${visible ? " modal-overlay--visible" : ""}`}
      onMouseDown={handleBackdropMouseDown}
      aria-hidden={!visible}
    >
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        tabIndex={-1}
        className={`modal-panel modal-panel--${size} ${visible ? "modal-panel--visible" : ""} ${className}`}
      >
        {(title || showCloseButton) && (
          <header className="modal-header">
            {title && (
              <h2 id={titleId} className="modal-title">
                {title}
              </h2>
            )}
            {showCloseButton && (
              <button
                type="button"
                className="modal-close"
                onClick={onClose}
                aria-label="Close dialog"
              >
                &times;
              </button>
            )}
          </header>
        )}

        <div className="modal-body">{children}</div>

        {footer && <footer className="modal-footer">{footer}</footer>}
      </div>
    </div>,
    document.body,
  );
}
```

