## Key behaviors

| Concern | Implementation |
|---|---|
| Darkened backdrop | `position: fixed` overlay with `rgba(15,23,42,.6)` + optional blur |
| Centered panel | Flexbox centering with `max-width` sizes and `max-height` for tall content |
| Escape to close | `keydown` listener on `document` (capture phase) |
| Backdrop click | `onMouseDown` with `event.target === event.currentTarget` so drags *from* the panel don't close it |
| Focus management | Focus moves to the panel on open, is trapped via Tab cycling, and restored to the trigger on close |
| Scroll lock | `body { overflow: hidden }` with scrollbar-width padding to prevent layout shift |
| Accessibility | `role="dialog"`, `aria-modal="true"`, `aria-labelledby` pointing at the title |
| Rendering | `createPortal` into `document.body` to escape parent `overflow`/`z-index` stacking contexts |

**Notes:** For a fully accessible implementation with focus restoration across portals and nested modals, consider `@headlessui/react` or `react-aria`'s `Dialog` instead of hand-rolling it. If you need the panel to be scrollable independently of the page, the `max-height` + `overflow-y: auto` on `.modal-body` above already handles that.

## `Modal.jsx`

```jsx
import { useCallback, useEffect, useId, useRef } from "react";
import { createPortal } from "react-dom";
import "./Modal.css";

const FOCUSABLE = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled]):not([type='hidden'])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  '[tabindex]:not([tabindex="-1"])',
].join(",");

export default function Modal({
  isOpen,
  onClose,
  title,
  description,
  children,
  footer,
  closeOnBackdropClick = true,
  closeOnEscape = true,
}) {
  const panelRef = useRef(null);
  const lastFocusedRef = useRef(null);
  const titleId = useId();
  const descriptionId = useId();

  // Lock page scroll while the modal is open
  useEffect(() => {
    if (!isOpen) return;
    const previous = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = previous;
    };
  }, [isOpen]);

  // Move focus into the dialog, restore it to the trigger on close
  useEffect(() => {
    if (!isOpen) return;
    lastFocusedRef.current = document.activeElement;
    const panel = panelRef.current;
    const first = panel?.querySelector(FOCUSABLE);
    (first ?? panel)?.focus();

    return () => lastFocusedRef.current?.focus?.();
  }, [isOpen]);

  // Escape closes the modal
  useEffect(() => {
    if (!isOpen || !closeOnEscape) return;
    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        onClose?.();
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [isOpen, closeOnEscape, onClose]);

  // Keep Tab focus cycling inside the panel
  const handlePanelKeyDown = useCallback((event) => {
    if (event.key !== "Tab") return;
    const panel = panelRef.current;
    if (!panel) return;

    const items = Array.from(panel.querySelectorAll(FOCUSABLE)).filter(
      (el) => el.offsetWidth > 0 || el.offsetHeight > 0 || el === document.activeElement
    );

    if (items.length === 0) {
      event.preventDefault();
      panel.focus();
      return;
    }

    const first = items[0];
    const last = items[items.length - 1];

    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  }, []);

  const handleBackdropMouseDown = (event) => {
    // Only close when the press started on the backdrop itself
    if (closeOnBackdropClick && event.target === event.currentTarget) {
      onClose?.();
    }
  };

  if (!isOpen) return null;

  return createPortal(
    <div className="modal-backdrop" onMouseDown={handleBackdropMouseDown}>
      <div
        ref={panelRef}
        className="modal-panel"
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        aria-describedby={description ? descriptionId : undefined}
        tabIndex={-1}
        onKeyDown={handlePanelKeyDown}
      >
        {(title || description) && (
          <header className="modal-header">
            <div className="modal-heading">
              {title && (
                <h2 id={titleId} className="modal-title">
                  {title}
                </h2>
              )}
              {description && (
                <p id={descriptionId} className="modal-description">
                  {description}
                </p>
              )}
            </div>
            <button
              type="button"
              className="modal-close"
              aria-label="Close dialog"
              onClick={onClose}
            >
              &times;
            </button>
          </header>
        )}

        <div className="modal-body">{children}</div>

        {footer && <footer className="modal-footer">{footer}</footer>}
      </div>
    </div>,
    document.body
  );
}
```

