            className="modal-close"
            onClick={onClose}
            aria-label="Close modal"
          >
            &times;
          </button>
        </header>

        <div className="modal-body">{children}</div>

        <footer className="modal-footer">
          <button className="modal-btn" onClick={onClose}>
            Close
          </button>
        </footer>
      </div>
    </div>
  );
}
```

